"""Write the tech stack and projects sections of README.md from .github/techstack.txt and
.github/projects.txt, aligned with spaces.

Each list: a category name on its own line, then one indented line per entry: `Name | link`
(or just `Name`). A blank line starts a new group; groups are separate paragraphs on the page.
Every list starts at the same place: each label is padded with Unicode spaces (em, en, thin…) up to
the widest label of both lists, using character widths measured in GitHub's font
(font-widths.json). Each category stays on one line; the script warns when one is wider than
MAX_WIDTH px, the width that fits GitHub's README column.
"""
import itertools, json, pathlib

ROOT = pathlib.Path(__file__).resolve().parents[2]
W = json.loads((ROOT / ".github/scripts/font-widths.json").read_text())
MAX_WIDTH = 830            # px; GitHub's README column is about 848 px wide on screens 1280 px and up
GAP = 20                   # px between the widest label and the lists
SPACES = [("&emsp;", "emsp"), ("&ensp;", "ensp"), ("&nbsp;", "nbsp"), ("&#8197;", "emsp14"), ("&thinsp;", "thinsp"), ("&#8202;", "hairsp")]
SECTIONS = {"tech stack": ".github/techstack.txt", "projects": ".github/projects.txt"}   # README section → list

def width(text, weight="regular"):
    return sum(W[weight].get(c, W[weight]["m"]) for c in text)

def pad(px):
    """The shortest run of space entities whose width is closest to px."""
    best = None
    for counts in itertools.product(range(int(px // W["spaces"]["emsp"]) + 2), range(2), range(3), range(2), range(3), range(3)):
        total = sum(n * W["spaces"][k] for n, (_, k) in zip(counts, SPACES))
        key = (abs(total - px), sum(counts))
        if best is None or key < best[0]:
            best = (key, counts)
    return "".join(e * n for n, (e, _) in zip(best[1], SPACES))

def read(path):
    """Categories as (label, [(name, link)]), and the indexes of categories that begin a group."""
    cats, starts = [], set()
    for line in (ROOT / path).read_text().splitlines():
        if not line.strip():
            starts.add(len(cats))
            continue
        if not line.startswith(" "):
            cats.append((line.strip(), []))
        else:
            name, _, link = (x.strip() for x in line.strip().partition("|"))
            cats[-1][1].append((name, link))
    return cats, starts

def render(cats, starts, column):
    sep = " · "
    blocks = []
    for label, items in cats:
        used = column + width(sep.join(n for n, _ in items))
        if used > MAX_WIDTH:
            print(f"warning: {label} is {used:.0f} px wide, over {MAX_WIDTH} px; it will wrap on GitHub")
        md = lambda n: n.replace("$", "\\$")       # a lone $ would start GitHub's inline maths
        links = sep.join(f"[{md(n)}]({l})" if l else md(n) for n, l in items)
        blocks.append(f"**{label}**" + pad(column - width(label, "semibold")) + links)
    body = ""
    for i, block in enumerate(blocks):
        body += ("\n\n" if i in starts else "<br>\n" if i else "") + block
    return body

def main():
    lists = {name: read(path) for name, path in SECTIONS.items()}
    # one label column for every section, so the tech stack and the projects line up with each other
    column = max(width(label, "semibold") for cats, _ in lists.values() for label, _ in cats) + GAP
    readme = ROOT / "README.md"
    text = readme.read_text()
    for name, (cats, starts) in lists.items():
        start, end = f"<!-- {name}: generated by .github/scripts/techstack.py -->", f"<!-- end {name} -->"
        text = text[:text.index(start)] + start + "\n" + render(cats, starts, column) + "\n" + end + text[text.index(end) + len(end):]
    readme.write_text(text)

if __name__ == "__main__":
    main()
